    col_cuts = [c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))]
    row_ranges = []
    start = 0
    for cut in row_cuts:
        if start < cut:
            row_ranges.append((start, cut))
        start = cut + 1
    if start < h:
        row_ranges.append((start, h))
    col_ranges = []
    start = 0
    for cut in col_cuts:
        if start < cut:
            col_ranges.append((start, cut))
        start = cut + 1
    if start < w:
        col_ranges.append((start, w))

    for r0, r1 in row_ranges:
        for left in range(0, len(col_ranges) - 1, 2):
            c0, c1 = col_ranges[left]
