        if start < n:
            result.append((start, n))
        return result

    rows = segments(h, [r for r in range(h) if all(v == sep for v in grid[r])])
    cols = segments(w, [c for c in range(w) if all(grid[r][c] == sep for r in range(h))])

    def pattern(rseg, cseg):
        r0, r1 = rows[rseg]
        c0, c1 = cols[cseg]
        return {(r-r0, c-c0, grid[r][c]) for r in range(r0, r1)
                for c in range(c0, c1) if grid[r][c] not in (0, sep)}

    active = set()
    # A pair is evidenced when any panel row contains nonempty matching reflected objects.
    for ri in range(len(rows)):
        for ci in range(len(cols) - 1):
            a, b = pattern(ri, ci), pattern(ri, ci + 1)
            if not a or not b:
                continue
            wa = cols[ci][1] - cols[ci][0]
            wb = cols[ci+1][1] - cols[ci+1][0]
            if wa != wb:
                continue
            reflected = {(r, wa - 1 - c, color) for r, c, color in a}
            if reflected == b:
