        c0, c1 = cols[ci]
        d0, d1 = cols[ci + 1]
        width = c1 - c0
        for r0, r1 in rows:
            a = [(r, c, grid[r][c]) for r in range(r0, r1) for c in range(c0, c1)
                 if grid[r][c] not in (0, sep)]
            b = [(r, c, grid[r][c]) for r in range(r0, r1) for c in range(d0, d1)
                 if grid[r][c] not in (0, sep)]
            if bool(a) == bool(b):
                continue
            if a:
                for r, c, color in a:
                    out[r][d0 + width - 1 - (c - c0)] = color
            else:
                for r, c, color in b:
