 "content": "def transform(grid):
    """Complete 2x2 panel patterns by mirroring a repeated motif across dividers."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Identify the grid-line color from complete rows and columns.
    divider = None
    for color in range(1, 10):
        if (any(all(v == color for v in row) for row in grid) and
                any(all(grid[r][c] == color for r in range(h)) for c in range(w))):
            divider = color
            break
    if divider is None:
        return out

    def get_segments(length, is_line):
        cuts = [i for i in range(length) if is_line(i)]
        segs, start = [], 0
        for cut in cuts:
            if start < cut:
                segs.append((start, cut))
            start = cut + 1
        if start < length:
            segs.append((start, length))
        return segs

    row_panels = get_segments(h, lambda r: all(v == divider for v in grid[r]))
    col_panels = get_segments(w, lambda c: all(grid[r][c] == divider for r in range(h)))

    def panel_pattern(rseg, cseg):
        r0, r1 = row_panels[rseg]
        c0, c1 = col_panels[cseg]
        return {(r-r0, c-c0, grid[r][c])
                for r in range(r0, r1) for c in range(c0, c1)
                if grid[r][c] not in (0, divider)}

    # For each adjacent 2x2 panel block, detect an existing motif whose
    # horizontal/vertical reflections account for all occupied panels.
    for ri in range(len(row_panels) - 1):
        r0, r1 = row_panels[ri]
        r2, r3 = row_panels[ri + 1]
        if r1 - r0 != r3 - r2:
            continue
        for ci in range(len(col_panels) - 1):
            c0, c1 = col_panels[ci]
            c2, c3 = col_panels[ci + 1]
            if c1 - c0 != c3 - c2:
                continue
            observed = {(dr, dc): panel_pattern(ri + dr, ci + dc)
                        for dr in (0, 1) for dc in (0, 1)}
            nonempty = [p for p in observed.values() if p]
            if len(nonempty) < 2:
                continue
            # Seek a base shape such that present tiles agree with appropriate flips.
            base = None
            for candidate in nonempty:
                ok = True
                for (dr, dc), shape in observed.items():
                    if not shape:
                        continue
                    expected = {(r if dr == 0 else (r1-r0-1-r),
                                 c if dc == 0 else (c1-c0-1-c), color)
                                for r, c, color in candidate}
                    if expected != shape:
                        ok = False
                        break
                if ok:
                    base = candidate
                    break
            if base is None:
                continue
            for (dr, dc), shape in observed.items():
                if shape:
                    continue
                rr0, rr1 = row_panels[ri + dr]
                cc0, cc1 = col_panels[ci + dc]
                for r, c, color in base:
                    rr = r if dr == 0 else (r1-r0-1-r)
                    cc = c if dc == 0 else (c1-c0-1-c)
                    out[rr0 + rr][cc0 + cc] = color
    return out

