 "content": "def transform(grid):
    """Complete reflected motifs within neighboring 2x2 blocks of panels."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    divider = next((color for color in range(1, 10)
                    if any(all(v == color for v in row) for row in grid)
                    and any(all(grid[r][c] == color for r in range(h)) for c in range(w))), None)
    if divider is None:
        return out

    def segments(n, is_line):
        cuts = [i for i in range(n) if is_line(i)]
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < n:
            result.append((start, n))
        return result

    rp = segments(h, lambda r: all(v == divider for v in grid[r]))
    cp = segments(w, lambda c: all(grid[r][c] == divider for r in range(h)))

    for ri in range(len(rp) - 1):
        r0, r1 = rp[ri]
        r2, r3 = rp[ri + 1]
        ph = r1 - r0
        if ph != r3 - r2:
            continue
        for ci in range(len(cp) - 1):
            c0, c1 = cp[ci]
            c2, c3 = cp[ci + 1]
            pw = c1 - c0
            if pw != c3 - c2:
                continue

            boxes = [(r0, r1, c0, c1), (r0, r1, c2, c3),
                     (r2, r3, c0, c1), (r2, r3, c2, c3)]
            normalized = []
            for k, (a, b, x, y) in enumerate(boxes):
                flip_r = k >= 2
                flip_c = k % 2 == 1
                shape = set()
                for r in range(a, b):
                    for c in range(x, y):
                        color = grid[r][c]
                        if color not in (0, divider):
                            u = (ph - 1 - (r - a)) if flip_r else (r - a)
                            v = (pw - 1 - (c - x)) if flip_c else (c - x)
                            shape.add((u, v, color))
                normalized.append(shape)

            active = [s for s in normalized if s]
            if len(active) < 2:
                continue
            # The observed pieces must be linked by overlap after alignment;
            # this distinguishes one incomplete repeated motif from unrelated marks.
            connected = {i for i, s in enumerate(normalized) if s}
            reached = {next(iter(connected))}
            while True:
                expanded = reached | {j for i in reached for j in connected
                                      if normalized[i] & normalized[j]}
                if expanded == reached:
                    break
                reached = expanded
            if reached != connected:
                continue

            motif = set().union(*active)
            for k, (a, b, x, y) in enumerate(boxes):
                flip_r = k >= 2
                flip_c = k % 2 == 1
                for u, v, color in motif:
                    rr = (ph - 1 - u) if flip_r else u
                    cc = (pw - 1 - v) if flip_c else v
                    out[a + rr][x + cc] = color
    return out

