            shapes = []
            for k, (a, b, x, y) in enumerate(boxes):
                flip_r, flip_c = (k >= 2), (k % 2 == 1)
                normalized = set()
                for r in range(a, b):
                    for c in range(x, y):
                        color = grid[r][c]
                        if color not in (0, divider):
                            u = b - 1 - r if flip_r else r - a
                            v = y - 1 - c if flip_c else c - x
                            normalized.add((u, v, color))
                shapes.append(normalized)

            occupied = [shape for shape in shapes if shape]
            # At least two matching observations establish the motif; every
            # occupied panel in this block must agree after reflection.
            if len(occupied) < 2 or any(shape != occupied[0] for shape in occupied[1:]):
                continue
            motif = occupied[0]
            for k, (a, b, x, y) in enumerate(boxes):
                if shapes[k]:
                    continue
                flip_r, flip_c = (k >= 2), (k % 2 == 1)
                for u, v, color in motif:
                    rr = b - 1 - u if flip_r else a + u
                    cc = y - 1 - v if flip_c else x + v
                    out[rr][cc] = color
    return out

